    public List<SuccessRow> findSuccesses(long sessionId) {
        throw new UnsupportedOperationException();
    }

    public List<FailureRow> findFailures(long sessionId) {
        throw new UnsupportedOperationException();
    }

    public int countSuccesses(long sessionId) {
        throw new UnsupportedOperationException();
    }
}
