        assertThat(detail.get("session").get("versionId").asLong()).isEqualTo(v2);
        assertThat(detail.get("cues")).hasSize(3);
        assertThat(detail.get("cues").get(1).get("durationSeconds").asInt()).isEqualTo(50);
        assertThat(v3).isNotEqualTo(v2);
    }
}
